//
// 2026-05-20 — converted from ES6 source to named AMD by hand because the
// Grunt build pipeline is not wired in this codebase yet. Once a grunt run
// is set up, this file will be regenerated from amd/src/. Until then, edits
// to behaviour must happen in BOTH amd/src/ (canonical ES6) and here
// (AMD-deployed). See ADR-002-followup tracking.

define('local_sentientia_programs/program_actions', [
    'core_form/modalform',
    'core/str',
    'core/notification',
    'core/ajax'
], function(ModalForm, Str, Notification, Ajax) {
    'use strict';

    var getString = Str.get_string;

    var STATUS = {DRAFT: 0, ACTIVE: 1, ARCHIVED: 2};

    // ─── Program-level actions (existing — index.php) ─────────────────────────

    var openProgramForm = function(programid, returnFocus) {
        var titleKey = (programid === 0) ? 'addprogram' : 'editprogram';
        return getString(titleKey, 'local_sentientia_programs').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_sentientia_programs\\form\\edit_program',
                args: {programid: programid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var confirmStatus = function(programid, name, newStatus, msgKey, returnFocus) {
        var titleKey = msgKey === 'confirmpublish' ? 'publishprogram'
                     : msgKey === 'confirmarchive' ? 'archiveprogram'
                     : 'draftprogram';
        return Promise.all([
            getString(titleKey, 'local_sentientia_programs'),
            getString(msgKey, 'local_sentientia_programs', name),
            getString('programstatuschanged', 'local_sentientia_programs')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], success = strings[2];
            Notification.confirm(title, message, title, null, function() {
                Ajax.call([{methodname: 'local_sentientia_programs_change_status',
                            args: {programid: programid, status: newStatus}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) {
                setTimeout(function() { returnFocus.focus(); }, 100);
            }
        });
    };

    var confirmDelete = function(programid, name, returnFocus) {
        return Promise.all([
            getString('deleteprogram', 'local_sentientia_programs'),
            getString('confirmdelete', 'local_sentientia_programs', name),
            getString('delete', 'core'),
            getString('programdeleted', 'local_sentientia_programs')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_sentientia_programs_delete_program',
                            args: {programid: programid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest('[data-action]');
        if (!trigger) { return; }
        var action = trigger.dataset.action;
        var programid = parseInt(trigger.dataset.programid || '0', 10);
        var name = trigger.dataset.name || 'this program';
        switch (action) {
            case 'create-program':  event.preventDefault(); openProgramForm(0, trigger); break;
            case 'edit-program':    event.preventDefault(); openProgramForm(programid, trigger); break;
            case 'publish-program': event.preventDefault(); confirmStatus(programid, name, STATUS.ACTIVE, 'confirmpublish', trigger); break;
            case 'archive-program': event.preventDefault(); confirmStatus(programid, name, STATUS.ARCHIVED, 'confirmarchive', trigger); break;
            case 'draft-program':   event.preventDefault(); confirmStatus(programid, name, STATUS.DRAFT, 'confirmdraft', trigger); break;
            case 'delete-program':  event.preventDefault(); confirmDelete(programid, name, trigger); break;
        }
    };

    // ─── View-page actions (G-03 — view.php levels/users tabs) ────────────────

    var openLevelForm = function(programid, levelid, returnFocus) {
        var titleKey = (levelid === 0) ? 'add_level' : 'edit_level';
        return getString(titleKey, 'local_sentientia_programs').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_sentientia_programs\\form\\edit_level',
                args: {programid: programid, levelid: levelid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var openEnrolUsersForm = function(programid, returnFocus) {
        return getString('enrol_users', 'local_sentientia_programs').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_sentientia_programs\\form\\enrol_program_users',
                args: {programid: programid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    // P1 #14 (2026-05-16) — bulk enrol by target audience.
    var openBulkEnrolAudienceForm = function(programid, returnFocus) {
        return getString('audience_modal_title', 'local_sentientia_programs').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_sentientia_programs\\form\\bulk_enrol_audience_form',
                args: {programid: programid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.LOADED, function() {
                var modalBody = document.querySelector('.modal.show .modal-body')
                    || document.querySelector('.modal-body');
                if (modalBody) {
                    // Was: const helper = await import('local_sentientia_programs/audience_form_helper');
                    // Replaced with AMD require() because dynamic import() isn't
                    // supported in the AMD-bundled context.
                    require(['local_sentientia_programs/audience_form_helper'], function(helper) {
                        helper.init(modalBody);
                    });
                }
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var enrolled = detail.enrolled || 0;
                var matched = detail.matched || 0;
                var message = enrolled === matched
                    ? 'Enrolled all ' + enrolled + ' matching user' + (enrolled === 1 ? '' : 's') + '.'
                    : enrolled + ' of ' + matched + ' matching users enrolled (rest were already enrolled).';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    // Phase F.3 (2026-05-08) — mass-enrol cohort modal.
    var openEnrolCohortForm = function(programid, returnFocus) {
        var modalForm = new ModalForm({
            formClass: 'local_sentientia_programs\\form\\enrol_program_cohort',
            args: {programid: programid},
            modalConfig: {title: 'Mass-enrol cohort', large: true},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
            var message = (event.detail && event.detail.message) || 'Cohort enrolled.';
            Notification.addNotification({message: message, type: 'success'});
            window.location.reload();
        });
        modalForm.show();
    };

    var confirmDeleteLevel = function(levelid, name, returnFocus) {
        return Promise.all([
            getString('delete_level', 'local_sentientia_programs'),
            getString('confirm_delete_level', 'local_sentientia_programs', name),
            getString('delete', 'core'),
            getString('leveldeleted', 'local_sentientia_programs')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_sentientia_programs_delete_level',
                            args: {levelid: levelid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var confirmUnenrolUser = function(programid, userid, name, returnFocus) {
        return Promise.all([
            getString('unenrol_user', 'local_sentientia_programs'),
            getString('confirm_unenrol_user', 'local_sentientia_programs', name),
            getString('remove', 'core'),
            getString('userunenrolled', 'local_sentientia_programs')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_sentientia_programs_unenrol_user',
                            args: {programid: programid, userid: userid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var handleViewClick = function(programid) {
        return function(event) {
            var trigger = event.target.closest('[data-action]');
            if (!trigger) { return; }
            var action = trigger.dataset.action;
            switch (action) {
                case 'add-level':
                    event.preventDefault();
                    openLevelForm(programid, 0, trigger);
                    break;
                case 'edit-level': {
                    event.preventDefault();
                    var lid = parseInt(trigger.dataset.levelid || '0', 10);
                    openLevelForm(programid, lid, trigger);
                    break;
                }
                case 'delete-level': {
                    event.preventDefault();
                    var lid2 = parseInt(trigger.dataset.levelid || '0', 10);
                    var n1 = trigger.dataset.name || 'this level';
                    confirmDeleteLevel(lid2, n1, trigger);
                    break;
                }
                case 'enrol-program-users':
                    event.preventDefault();
                    openEnrolUsersForm(programid, trigger);
                    break;
                case 'bulk-enrol-audience':
                    event.preventDefault();
                    openBulkEnrolAudienceForm(programid, trigger);
                    break;
                case 'enrol-program-cohort':
                    event.preventDefault();
                    openEnrolCohortForm(programid, trigger);
                    break;
                case 'unenrol-program-user': {
                    event.preventDefault();
                    var uid = parseInt(trigger.dataset.userid || '0', 10);
                    var n2 = trigger.dataset.name || 'this user';
                    confirmUnenrolUser(programid, uid, n2, trigger);
                    break;
                }
            }
        };
    };

    // ─── Level-courses sub-page actions (G-03 — levelcourses.php) ─────────────

    var openAssignCoursesForm = function(levelid, returnFocus) {
        return getString('add_courses', 'local_sentientia_programs').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_sentientia_programs\\form\\assign_level_courses',
                args: {levelid: levelid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var confirmUnassignCourse = function(levelid, courseid, name, returnFocus) {
        return Promise.all([
            getString('add_courses', 'local_sentientia_programs'),
            getString('confirm_unassign_course', 'local_sentientia_programs', name),
            getString('remove', 'core'),
            getString('courseunassigned', 'local_sentientia_programs')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_sentientia_programs_unassign_level_course',
                            args: {levelid: levelid, courseid: courseid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var handleLevelCoursesClick = function(levelid) {
        return function(event) {
            var trigger = event.target.closest('[data-action]');
            if (!trigger) { return; }
            var action = trigger.dataset.action;
            switch (action) {
                case 'add-level-courses':
                    event.preventDefault();
                    openAssignCoursesForm(levelid, trigger);
                    break;
                case 'unassign-level-course': {
                    event.preventDefault();
                    var cid = parseInt(trigger.dataset.courseid || '0', 10);
                    var name = trigger.dataset.name || 'this course';
                    confirmUnassignCourse(levelid, cid, name, trigger);
                    break;
                }
            }
        };
    };

    var init = function() {
        var root = document.querySelector('[data-region="airpay-programs"]') || document.body;
        if (root.dataset.airpayProgramsInit === '1') { return; }
        root.dataset.airpayProgramsInit = '1';
        root.addEventListener('click', handleClick);
    };

    var initView = function(programid) {
        var root = document.querySelector('[data-region="airpay-programs-view"]') || document.body;
        if (root.dataset.airpayProgramsViewInit === '1') { return; }
        root.dataset.airpayProgramsViewInit = '1';
        root.addEventListener('click', handleViewClick(programid));
    };

    var initLevelCourses = function(levelid) {
        var root = document.querySelector('[data-region="airpay-level-courses"]') || document.body;
        if (root.dataset.airpayLevelCoursesInit === '1') { return; }
        root.dataset.airpayLevelCoursesInit = '1';
        root.addEventListener('click', handleLevelCoursesClick(levelid));
    };

    return {
        init: init,
        initView: initView,
        initLevelCourses: initLevelCourses
    };
});
